"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

import { Dialog } from "./dialog";

export interface CommandItem {
  label: string;
  hint?: React.ReactNode;
  keywords?: string;
  onSelect?: () => void;
}

export interface CommandGroup {
  label?: string;
  items: CommandItem[];
}

export interface CommandProps extends React.HTMLAttributes<HTMLDivElement> {
  groups: CommandGroup[];
  placeholder?: string;
  emptyLabel?: React.ReactNode;
  onDone?: () => void;
}

const styles = stylex.create({
  palette: {
    width: {
      default: 480,
      [mq.phone]: "100%",
    },
    maxWidth: {
      default: "90vw",
      [mq.phone]: "100%",
    },
    padding: 0,
    overflow: "hidden",
  },
  input: {
    boxSizing: "border-box",
    width: "100%",
    borderWidth: 0,
    borderBottomWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    backgroundColor: "transparent",
    fontFamily: "inherit",
    fontSize: {
      default: 14,
      [mq.phone]: 16,
    },
    letterSpacing: "-0.01em",
    color: raster.ink,
    paddingBlock: 14,
    paddingInline: 16,
    outline: "none",
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
    "::placeholder": {
      color: raster.gray,
    },
  },
  list: {
    maxHeight: 320,
    overflowY: "auto",
    padding: 6,
  },
  group: {
    fontSize: {
      default: 11,
      [mq.phone]: 13,
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.gray,
    paddingTop: {
      default: 8,
      [mq.phone]: 12,
    },
    paddingRight: {
      default: 10,
      [mq.phone]: 14,
    },
    paddingBottom: {
      default: 4,
      [mq.phone]: 6,
    },
    paddingLeft: {
      default: 10,
      [mq.phone]: 14,
    },
  },
  item: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 12,
    width: "100%",
    textAlign: "left",
    borderWidth: 0,
    backgroundColor: "transparent",
    fontFamily: "inherit",
    fontSize: {
      default: 13.5,
      [mq.phone]: raster.controlFs,
    },
    letterSpacing: "-0.01em",
    color: raster.ink,
    paddingBlock: {
      default: 8,
      [mq.phone]: 12,
    },
    paddingInline: {
      default: 10,
      [mq.phone]: 14,
    },
    borderRadius: {
      default: raster.radiusSm,
      [mq.phone]: 0,
    },
    cursor: "pointer",
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
  },
  itemActive: {
    backgroundColor: raster.dividerSubtle,
  },
  hint: {
    fontSize: 11,
    color: raster.gray,
  },
  empty: {
    padding: {
      default: 20,
      [mq.phone]: 24,
    },
    textAlign: "center",
    fontSize: {
      default: 13,
      [mq.phone]: 15,
    },
    color: raster.gray,
  },
});

/** Filter, arrows, enter. */
export function Command({
  groups,
  placeholder = "Type a command or search…",
  emptyLabel = "Nothing found.",
  onDone,
  className,
  style,
  ...props
}: CommandProps) {
  const [query, setQuery] = React.useState("");
  const [activeIndex, setActiveIndex] = React.useState(0);

  const q = query.toLowerCase();
  const filtered = groups
    .map((group) => ({
      ...group,
      items: group.items.filter(
        (item) => item.label.toLowerCase().includes(q) || item.keywords?.toLowerCase().includes(q),
      ),
    }))
    .filter((group) => group.items.length > 0);
  const flat = filtered.flatMap((group) => group.items);

  const run = (item: CommandItem) => {
    onDone?.();
    item.onSelect?.();
  };

  const input = rs(["rs-command-input"], styles.input);
  const list = rs(["rs-command-list"], styles.list);
  const empty = rs(["rs-command-empty"], styles.empty);
  const groupSx = rs(["rs-command-group"], styles.group);
  const hint = rs(["rs-command-hint"], styles.hint);

  let cursor = -1;
  return (
    <div className={className} style={style} {...props}>
      <input
        className={input.className}
        style={input.style}
        autoFocus
        placeholder={placeholder}
        role="combobox"
        aria-expanded="true"
        aria-label="Command"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setActiveIndex(0);
        }}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") {
            e.preventDefault();
            setActiveIndex((i) => Math.min(flat.length - 1, i + 1));
          }
          if (e.key === "ArrowUp") {
            e.preventDefault();
            setActiveIndex((i) => Math.max(0, i - 1));
          }
          if (e.key === "Enter") {
            e.preventDefault();
            const item = flat[activeIndex];
            if (item) run(item);
          }
        }}
      />
      <div className={list.className} style={list.style} role="listbox">
        {flat.length === 0 && (
          <div className={empty.className} style={empty.style}>
            {emptyLabel}
          </div>
        )}
        {filtered.map((group, gi) => (
          <React.Fragment key={gi}>
            {group.label && (
              <div className={groupSx.className} style={groupSx.style}>
                {group.label}
              </div>
            )}
            {group.items.map((item) => {
              cursor++;
              const index = cursor;
              const row = rs(
                ["rs-command-item", index === activeIndex && "rs-command-item-active"],
                styles.item,
                index === activeIndex && styles.itemActive,
              );
              return (
                <button
                  key={item.label}
                  type="button"
                  role="option"
                  aria-selected={index === activeIndex}
                  className={row.className}
                  style={row.style}
                  onPointerEnter={() => setActiveIndex(index)}
                  onClick={() => run(item)}
                >
                  <span>{item.label}</span>
                  {item.hint != null && (
                    <span className={hint.className} style={hint.style}>
                      {item.hint}
                    </span>
                  )}
                </button>
              );
            })}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}

export interface CommandDialogProps extends CommandProps {
  open: boolean;
  onClose?: () => void;
}

/** The palette in a native <dialog>. Wire ⌘K in your app to setOpen(true). */
export function CommandDialog({ open, onClose, className, ...props }: CommandDialogProps) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      className={["rs-command", "rs-command-dialog", className].filter(Boolean).join(" ")}
      extraStyles={[styles.palette]}
    >
      {open && <Command onDone={onClose} {...props} />}
    </Dialog>
  );
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import type { CompiledStyles, InlineStyles } from "@stylexjs/stylex";
import { cx } from "./cx";

type Nested<T> = T | ReadonlyArray<Nested<T>>;

/** Exactly what stylex.props accepts: compiled leaves, falsy, nested arrays, or a leaf with inline styles. */
export type Leaves = ReadonlyArray<Nested<null | undefined | CompiledStyles | boolean | Readonly<[CompiledStyles, InlineStyles]>>>;

type StyleXProps = { className?: string; style?: CSSProperties };

/**
 * The one seam every component styles through: semantic rs-* class names
 * (the CSS-first contract, and what packages/core generates CSS for) merged
 * with the compiled StyleX leaves that paint the React tree.
 */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: Leaves): StyleXProps {
  const sx = stylex.props(...styles) as StyleXProps;
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs, type Leaves } from "./rs";

const phone = mq.phone;

export interface DialogProps extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "open"> {
  open: boolean;
  onClose?: () => void;
  /** Extra StyleX leaves merged after the dialog frame (command palette). */
  extraStyles?: Leaves;
}

export const dialogStyles = stylex.create({
  frame: {
    boxSizing: "border-box",
    maxWidth: {
      default: 320,
      [mq.phone]: "calc(100vw - 32px)",
    },
    width: {
      default: null,
      [mq.phone]: "calc(100vw - 32px)",
    },
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: raster.radiusSm,
    padding: {
      default: 20,
      [mq.phone]: "24px 20px",
    },
    backgroundColor: raster.paper,
    color: raster.ink,
    boxShadow: "none",
    "::backdrop": {
      backgroundColor: "rgba(0,0,0,0.25)",
    },
  },
  title: {
    display: "block",
    fontSize: {
      default: 15,
      [mq.phone]: 18,
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.ink,
    marginBottom: {
      default: 6,
      [mq.phone]: 10,
    },
  },
  body: {
    fontSize: {
      default: 13.5,
      [mq.phone]: 16,
    },
    color: raster.gray,
    letterSpacing: "-0.01em",
    lineHeight: 1.55,
    marginTop: 0,
    marginRight: 0,
    marginBottom: {
      default: 16,
      [mq.phone]: 20,
    },
    marginLeft: 0,
  },
  actions: {
    display: "flex",
    justifyContent: "flex-end",
    flexDirection: {
      default: "row",
      [mq.phone]: "column",
    },
    alignItems: {
      default: "flex-end",
      [mq.phone]: "stretch",
    },
    gap: {
      default: 8,
      [mq.phone]: 10,
    },
  },
});

/**
 * A native <dialog>. Focus trapping, Escape, and the backdrop come
 * from the platform.
 */
export function Dialog({
  open,
  onClose,
  className,
  style,
  children,
  extraStyles,
  ...props
}: DialogProps) {
  const ref = React.useRef<HTMLDialogElement>(null);

  React.useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    else if (!open && dialog.open) dialog.close();
  }, [open]);

  const sx = rs(["rs-dialog", className], dialogStyles.frame, ...((extraStyles ?? []) as Leaves));
  return (
    <dialog
      ref={ref}
      className={sx.className}
      style={{ ...sx.style, ...style }}
      onClose={() => onClose?.()}
      {...props}
    >
      {children}
    </dialog>
  );
}

export function DialogTitle({ className, style, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  const sx = rs(["rs-dialog-title", className], dialogStyles.title);
  return <span {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function DialogBody({ className, style, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  const sx = rs(["rs-dialog-body", className], dialogStyles.body);
  return <p {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function DialogActions({ className, style, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  const sx = rs(["rs-dialog-actions", className], dialogStyles.actions);
  return (
    <div {...props} className={sx.className} style={{ ...sx.style, ...style }}>
      {React.Children.map(children, (child) => {
        if (!React.isValidElement<{ style?: React.CSSProperties }>(child)) return child;
        return React.cloneElement(child, {
          style: { ...child.props.style, borderRadius: 0 },
        });
      })}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
